import{_ as l,a0 as o,w as p,s as d,I as i,x as s,a1 as t,A as n,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const S=JSON.parse('{"title":"用 Samba 跨平台共享文件 | LCTT x X-CMD","titleTemplate":false,"description":"用 Samba 跨平台共享文件 | LCTT (202201) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用 Samba 跨平台共享文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用 Samba 跨平台共享文件 | LCTT (202201) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202201/20211219 Open source file sharing with this Linux tool","title":"用 Samba 跨平台共享文件","tag":"202201","desc":""},"relativePath":"202201/20211219 Open source file sharing with this Linux tool.md","filePath":"[post].md"}'),b={name:"202201/20211219 Open source file sharing with this Linux tool.md"};function h(u,a,g,m,k,f){const e=o("Link");return p(),d("div",null,[a[24]||(a[24]=i("h1",{id:"用-samba-跨平台共享文件",tabindex:"-1"},[s("用 Samba 跨平台共享文件 "),i("a",{class:"header-anchor",href:"#用-samba-跨平台共享文件","aria-label":"Permalink to “用 Samba 跨平台共享文件”"},"​")],-1)),a[25]||(a[25]=i("blockquote",null,[i("p",null,"Samba 是一種靈活的文件共享工具，它將你可能在組織中運行的所有不同平台結合在一起。")],-1)),a[26]||(a[26]=i("p",null,[i("img",{src:"https://img.linux.net.cn/data/attachment/album/202201/04/092708dsjqu1fbfjjhee1j.jpg",alt:""})],-1)),a[27]||(a[27]=i("p",null,"在我接觸 Linux 的早期，我是紐約州一個小型學前教育學區的技術總監。我們的技術預算總是捉襟見肘。我們是一個 Windows 2000 活動目錄域，但我們的中央服務器磁盤空間有限，而且沒有教師的主目錄。此外，我們經歷過十幾次員工電腦硬盤故障。",-1)),a[28]||(a[28]=i("p",null,"我正在尋找一種方法，以最小的成本保存員工的工作。這時我發現了 Samba。在那之前，我一直將 Linux 用於內容過濾，不知道我們的 Windows 工作站可以連接到服務器並保存文件備份。",-1)),i("p",null,[t(e,{href:"https://www.samba.org/"},{default:n(()=>[...a[0]||(a[0]=[s("Samba 項目",-1)])]),_:1}),a[1]||(a[1]=s(" 自 1992 年以來一直存在。當我開始試驗這個項目的時候，這個項目已經有 10 年曆史了，我對如何配置它一無所知。我買了一本書並閲讀了如何實現它，然後我從我們的電腦櫃中取出一台舊電腦，購買了一個 300G 的希捷 IDE 驅動器，安裝了 Linux，並配置了 Samba。我使用了一個簡單的配置，並且它成功了。在向我們的一個 IT 助理展示後，我們部署了這個解決方案。硬盤故障的問題繼續存在，但我們的員工不再需要擔心失去他們所有的辛苦工作。",-1))]),i("p",null,[a[5]||(a[5]=s("Samba 採用 ",-1)),t(e,{href:"https://www.samba.org/samba/docs/GPL.html"},{default:n(()=>[...a[2]||(a[2]=[s("GPL",-1)])]),_:1}),a[6]||(a[6]=s(" 許可證，並在大多數 Linux 發行版上廣泛使用。Samba 有很好的 ",-1)),t(e,{href:"https://www.samba.org/samba/docs/"},{default:n(()=>[...a[3]||(a[3]=[s("文檔",-1)])]),_:1}),a[7]||(a[7]=s("，Fedora 用户可以查閲這份在 ",-1)),t(e,{href:"https://docs.fedoraproject.org/en-US/quick-docs/samba/"},{default:n(()=>[...a[4]||(a[4]=[s("Fedora 上配置 Samba",-1)])]),_:1}),a[8]||(a[8]=s(" 的文檔。",-1))]),a[29]||(a[29]=r(`<h3 id="在-linux-上安裝-samba" tabindex="-1">在 Linux 上安裝 Samba <a class="header-anchor" href="#在-linux-上安裝-samba" aria-label="Permalink to “在 Linux 上安裝 Samba”">​</a></h3><p>你可以使用你的發行版的包管理器來安裝 Samba。</p><p>在 Fedora、CentOS、RHEL、Mageia 和類似的系統上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install samba</span></span></code></pre></div><p>在 Debian, Linux Mint 和類似系統上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install samba</span></span></code></pre></div><h3 id="用-samba-創建一個共享文件夾" tabindex="-1">用 Samba 創建一個共享文件夾 <a class="header-anchor" href="#用-samba-創建一個共享文件夾" aria-label="Permalink to “用 Samba 創建一個共享文件夾”">​</a></h3><p>創建一個簡單的共享文件夾只需要五個步驟。</p><p>1、在你的 Linux 服務器上創建一個你希望用户能夠保存共享文件的目錄。這個目錄可以是服務器上的任何地方：在 <code>/home</code> 或 <code>/opt</code> 或任何最適合你的地方。我使用我的主目錄，我把共享目錄稱為 <code>sambashare</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mkdir /home/don/sambashare</span></span></code></pre></div><p>在 Fedora 和其他運行 SELinux 的發行版上，你必須對這個共享目錄給予安全許可：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo semanage fcontext --add --type &quot;samba_share_t&quot; ~/sambashare</span></span>
<span class="line"><span>$ sudo restorecon -R ~/sambashare</span></span></code></pre></div><p>2、用 Nano 或你選擇的文本編輯器編輯 Samba 配置文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo nano /etc/samba/smb.conf</span></span></code></pre></div><p>在 <code>smb.conf</code> 文件的底部添加以下內容，用你自己的共享目錄的位置替換我例子中的 <code>/home/don/sambashare</code> 路徑：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[sambashare]</span></span>
<span class="line"><span>        comment = Samba on Linux       </span></span>
<span class="line"><span>        path = /home/don/sambashare</span></span>
<span class="line"><span>        read only = no</span></span>
<span class="line"><span>        browsable = yes</span></span></code></pre></div><p>如果你使用 Nano，按 <code>Ctrl-O</code>，然後按<strong>回車</strong>來保存，按 <code>Ctrl-X</code> 退出。</p><p>3、啓動或重啓 Samba 服務，這取決於你的發行版。</p><p>在 Fedora 和類似的系統中，沒有明確的許可，服務是不會啓動的，所以現在就可以啓動 Samba，並在啓動時啓動：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl enable –now smb.conf</span></span></code></pre></div><p>在 Debian 和類似系統中，Samba 默認在安裝後啓動，所以你必須現在就重啓它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo service smbd restart</span></span></code></pre></div><p>4、更新你的防火牆規則，允許訪問你的 Samba 共享。該如何做取決於你的系統使用什麼防火牆。</p><p>如果你正在運行 firewalld：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo firewall-cmd --permanent --add-service=samba</span></span>
<span class="line"><span>$ sudo firewall-cmd --reload</span></span></code></pre></div><p>如果你正在運行 UFW：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo ufw allow samba</span></span></code></pre></div><p>5、現在你需要設置一個密碼來訪問你的 Samba 共享。這個用户名（在我的例子中是 don）必須屬於你係統中的一個賬户。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo smbpasswd -a don</span></span></code></pre></div><p>我在每個 Samba 共享中都放置了一個簡單的 <code>README</code> 文件，這樣用户就會明白這個目錄位於服務器上，他們必須在 VPN 上才能從家裏訪問它等等。</p><h3 id="從-windows-和-mac-訪問-samba" tabindex="-1">從 Windows 和 Mac 訪問 Samba <a class="header-anchor" href="#從-windows-和-mac-訪問-samba" aria-label="Permalink to “從 Windows 和 Mac 訪問 Samba”">​</a></h3><p>在 Windows 電腦上，打開文件管理器（Windows Explorer），訪問路徑 <code>ip-address-of-the-Linux-computer/sambashare</code>。系統會提示你輸入 Samba 共享密碼，然後 <code>sambashare</code> 目錄中的文件會出現在你的文件管理器窗口中，就像它們存在於你的桌面上一樣。你可以開始在網絡上的這個新共享目錄中存儲你的文件。</p><p>在 macOS 電腦上，進入 Finder 菜單，選擇 Go。在出現的對話框中，輸入 <code>smb://ip-address/sambashare</code>，並按照提示輸入 Samba 密碼。</p><h3 id="samba-意味着共享" tabindex="-1">Samba 意味着共享 <a class="header-anchor" href="#samba-意味着共享" aria-label="Permalink to “Samba 意味着共享”">​</a></h3><p>Samba 使共享文件變得容易。你可以在 Samba 中使用許多其他方案來創建共享位置，包括用户組的公共文件夾，只接受傳入文件的收件箱，以及其他你可能需要的東西。它是開源的、靈活的，而且它把你可能在你的辦公室裏運行的所有不同的平台聯合起來。</p><hr>`,36)),i("p",null,[a[10]||(a[10]=s("via: ",-1)),t(e,{href:"https://opensource.com/article/21/12/file-sharing-linux-samba"},{default:n(()=>[...a[9]||(a[9]=[s("https://opensource.com/article/21/12/file-sharing-linux-samba",-1)])]),_:1})]),i("p",null,[a[15]||(a[15]=s("作者：",-1)),t(e,{href:"https://opensource.com/users/don-watkins"},{default:n(()=>[...a[11]||(a[11]=[s("Don Watkins",-1)])]),_:1}),a[16]||(a[16]=s(" 選題：",-1)),t(e,{href:"https://github.com/lujun9972"},{default:n(()=>[...a[12]||(a[12]=[s("lujun9972",-1)])]),_:1}),a[17]||(a[17]=s(" 譯者：",-1)),t(e,{href:"https://github.com/geekpi"},{default:n(()=>[...a[13]||(a[13]=[s("geekpi",-1)])]),_:1}),a[18]||(a[18]=s(" 校對：",-1)),t(e,{href:"https://github.com/wxy"},{default:n(()=>[...a[14]||(a[14]=[s("wxy",-1)])]),_:1})]),i("p",null,[a[21]||(a[21]=s("本文由 ",-1)),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...a[19]||(a[19]=[s("LCTT",-1)])]),_:1}),a[22]||(a[22]=s(" 原創編譯，",-1)),t(e,{href:"https://linux.cn/"},{default:n(()=>[...a[20]||(a[20]=[s("Linux中國",-1)])]),_:1}),a[23]||(a[23]=s(" 榮譽推出",-1))])])}const C=l(b,[["render",h]]);export{S as __pageData,C as default};
